package cl.sonidovivo;

import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;

class NotFoundException extends RuntimeException{NotFoundException(String m){super(m);}} class BadRequestException extends RuntimeException{BadRequestException(String m){super(m);}} class UnauthorizedException extends RuntimeException{UnauthorizedException(String m){super(m);}}
@Service @Transactional class AuthService { private final UsuarioRepository usuarios;private final PasswordEncoder encoder;private final JwtService jwt; AuthService(UsuarioRepository u,PasswordEncoder e,JwtService j){usuarios=u;encoder=e;jwt=j;}
  AuthResponse login(LoginRequest r){Usuario u=usuarios.findByEmailIgnoreCase(r.email()).orElseThrow(()->new UnauthorizedException("Correo o contraseña incorrectos"));if(!u.activo||!encoder.matches(r.password(),u.password))throw new UnauthorizedException("Correo o contraseña incorrectos");return new AuthResponse(jwt.generar(u),Mapper.usuario(u));}
  UsuarioResponse registro(RegistroRequest r){if(usuarios.existsByEmailIgnoreCase(r.email()))throw new BadRequestException("Ya existe una cuenta con ese correo");Usuario u=new Usuario(r.nombre().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password()),Rol.CLIENTE);u.telefono=r.telefono();u.direccion=r.direccion();u.comuna=r.comuna();u.region=r.region();return Mapper.usuario(usuarios.save(u));}
}
@Service @Transactional class ProductoService {private final ProductoRepository repo;ProductoService(ProductoRepository r){repo=r;}
  @Transactional(readOnly=true) Page<ProductoResponse> listar(String busqueda,String categoria,String stock,String orden,int pagina,int tamanio){String campo=switch(orden==null?"":orden){case "precio","precioDesc"->"precio";case "nombre"->"nombre";default->"fechaCreacion";};Sort.Direction dir="precioDesc".equals(orden)?Sort.Direction.DESC:Sort.Direction.ASC;return repo.buscar(blank(busqueda),blank(categoria),blank(stock),PageRequest.of(Math.max(pagina,0),Math.min(Math.max(tamanio,1),100),Sort.by(dir,campo))).map(Mapper::producto);}
  @Transactional(readOnly=true) ProductoResponse uno(Long id){return Mapper.producto(producto(id));} ProductoResponse crear(ProductoRequest r){if(repo.existsByCodigoIgnoreCase(r.codigo()))throw new BadRequestException("El código de producto ya existe");Producto p=new Producto();copy(r,p);return Mapper.producto(repo.save(p));} ProductoResponse actualizar(Long id,ProductoRequest r){Producto p=producto(id);if(!p.codigo.equalsIgnoreCase(r.codigo())&&repo.existsByCodigoIgnoreCase(r.codigo()))throw new BadRequestException("El código de producto ya existe");copy(r,p);return Mapper.producto(p);} void eliminar(Long id){repo.delete(producto(id));} Producto producto(Long id){return repo.findById(id).orElseThrow(()->new NotFoundException("Producto no encontrado"));}
  private void copy(ProductoRequest r,Producto p){p.codigo=r.codigo().trim().toUpperCase();p.nombre=r.nombre().trim();p.categoria=r.categoria().trim();p.marca=r.marca();p.modelo=r.modelo();p.descripcion=r.descripcion();p.precio=r.precio();p.stock=r.stock();p.imagen=r.imagen();p.oferta=r.oferta();}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
@Service @Transactional class PedidoService {private final PedidoRepository pedidos;private final ProductoService productos;private final UsuarioRepository usuarios;PedidoService(PedidoRepository p,ProductoService pr,UsuarioRepository u){pedidos=p;productos=pr;usuarios=u;}
  @Transactional(readOnly=true) List<PedidoResponse> listarCliente(String email){return pedidos.findByClienteIdOrderByFechaPedidoDesc(cliente(email).id).stream().map(Mapper::pedido).toList();}
  @Transactional(readOnly=true) PedidoResponse detalle(Long id,String email,boolean operador){Pedido p=pedido(id);if(!operador&&!p.cliente.email.equalsIgnoreCase(email))throw new org.springframework.security.access.AccessDeniedException("No puede consultar este pedido");return Mapper.pedido(p);}
  PedidoResponse crear(String email,PedidoRequest r){Pedido p=new Pedido();p.cliente=cliente(email);p.codigoPedido="PED-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();p.total=BigDecimal.ZERO;for(ItemPedidoRequest item:r.items()){Producto producto=productos.producto(item.productoId());if(producto.stock<item.cantidad())throw new BadRequestException("Stock insuficiente para "+producto.nombre);producto.stock-=item.cantidad();ItemPedido i=new ItemPedido();i.pedido=p;i.producto=producto;i.cantidad=item.cantidad();i.precioUnitario=producto.precio;p.items.add(i);p.total=p.total.add(producto.precio.multiply(BigDecimal.valueOf(item.cantidad())));}HistorialEstado h=new HistorialEstado();h.pedido=p;h.estado=EstadoPedido.Confirmado;p.historial.add(h);return Mapper.pedido(pedidos.save(p));}
  PedidoResponse estado(Long id,CambioEstadoRequest r){Pedido p=pedido(id);if(r.estado().ordinal()<p.estado.ordinal()||r.estado().ordinal()>p.estado.ordinal()+1)throw new BadRequestException("El pedido solo puede avanzar al siguiente estado");if(r.estado()==p.estado)return Mapper.pedido(p);p.estado=r.estado();p.fechaActualizacion=Instant.now();HistorialEstado h=new HistorialEstado();h.pedido=p;h.estado=r.estado();p.historial.add(h);return Mapper.pedido(p);}
  private Pedido pedido(Long id){return pedidos.findById(id).orElseThrow(()->new NotFoundException("Pedido no encontrado"));}private Usuario cliente(String email){return usuarios.findByEmailIgnoreCase(email).orElseThrow(()->new NotFoundException("Usuario no encontrado"));}
}
@Service @Transactional class UsuarioService {private final UsuarioRepository repo;private final PasswordEncoder encoder;UsuarioService(UsuarioRepository r,PasswordEncoder e){repo=r;encoder=e;}@Transactional(readOnly=true) List<UsuarioResponse> listar(){return repo.findAll().stream().map(Mapper::usuario).toList();}@Transactional(readOnly=true) UsuarioResponse uno(Long id){return Mapper.usuario(entidad(id));}UsuarioResponse actualizar(Long id,UsuarioRequest r){Usuario u=entidad(id);if(!u.email.equalsIgnoreCase(r.email())&&repo.existsByEmailIgnoreCase(r.email()))throw new BadRequestException("El correo ya está en uso");u.nombre=r.nombre();u.email=r.email().toLowerCase();u.username=u.email;u.telefono=r.telefono();u.direccion=r.direccion();u.comuna=r.comuna();u.region=r.region();if(r.rol()!=null)u.rol=r.rol();if(r.activo()!=null)u.activo=r.activo();return Mapper.usuario(u);}void eliminar(Long id){repo.delete(entidad(id));}private Usuario entidad(Long id){return repo.findById(id).orElseThrow(()->new NotFoundException("Usuario no encontrado"));}}
@Service @Transactional class MensajeService {private final MensajeContactoRepository contactos;private final SolicitudReparacionRepository reparaciones;MensajeService(MensajeContactoRepository c,SolicitudReparacionRepository r){contactos=c;reparaciones=r;}MensajeResponse contacto(ContactoRequest r){MensajeContacto m=new MensajeContacto();m.nombre=r.nombre();m.correo=r.correo();m.mensaje=r.mensaje();return Mapper.contacto(contactos.save(m));}MensajeResponse reparacion(ReparacionRequest r){SolicitudReparacion s=new SolicitudReparacion();s.nombre=r.nombre();s.correo=r.correo();s.telefono=r.telefono();s.tipoInstrumento=r.tipoInstrumento();s.marcaModelo=r.marcaModelo();s.servicio=r.servicio();s.descripcion=r.descripcion();s.entrega=r.entrega();return Mapper.reparacion(reparaciones.save(s));}@Transactional(readOnly=true)List<MensajeResponse> listar(){List<MensajeResponse> salida=new ArrayList<>();contactos.findAll().forEach(x->salida.add(Mapper.contacto(x)));reparaciones.findAll().forEach(x->salida.add(Mapper.reparacion(x)));salida.sort(Comparator.comparing(MensajeResponse::fecha).reversed());return salida;}}
class Mapper {static UsuarioResponse usuario(Usuario u){return new UsuarioResponse(u.id,u.username,u.nombre,u.email,u.rol,u.activo,u.telefono,u.direccion,u.comuna,u.region,u.fechaCreacion);}static ProductoResponse producto(Producto p){return new ProductoResponse(p.id,p.codigo,p.nombre,p.categoria,p.marca,p.modelo,p.descripcion,p.precio,p.stock,p.imagen,p.oferta,p.fechaCreacion);}static PedidoResponse pedido(Pedido p){return new PedidoResponse(p.id,p.codigoPedido,usuario(p.cliente),p.estado,p.total,p.fechaPedido,p.fechaActualizacion,p.items.stream().map(i->new ItemPedidoResponse(i.id,i.producto.id,i.producto.codigo,i.producto.nombre,i.cantidad,i.precioUnitario)).toList(),p.historial.stream().map(h->new HistorialResponse(h.estado,h.fecha)).toList());}static MensajeResponse contacto(MensajeContacto m){return new MensajeResponse(m.id,"contacto",m.nombre,m.correo,null,null,null,null,null,null,m.mensaje,m.fecha,m.respuesta,m.fechaRespuesta,m.estado);}static MensajeResponse reparacion(SolicitudReparacion s){return new MensajeResponse(s.id,"reparacion",s.nombre,s.correo,s.telefono,s.tipoInstrumento,s.marcaModelo,s.servicio,s.descripcion,s.entrega,null,s.fecha,s.respuesta,s.fechaRespuesta,s.estado);}}